import org.jsoup.nodes.Element;
import org.junit.Test;
import static org.junit.Assert.*;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

@RunWith(JUnit4.class)
public class ElementTest {

    @Mock
    private Tag tag;

    public ElementTest() {
        MockitoAnnotations.initMocks(this);
    }

    // Tag related tests

    @Test
    public void createElementWithTag_ReturnsElementWithCorrectTag() {
        Element element = new Element(tag, null, null);
        assertEquals(tag, element.tag());
    }

    @Test
    public void getTag_WhenElementIsNotCreated_ReturnsNull() {
        assertNull(Element.create(tag).tag());
    }

    // Attributes related tests

    @Test
    public void createElementWithAttributes_ReturnsElementWithCorrectAttributes() {
        Element element = new Element(tag, "key", "value");
        assertEquals("key", element.attr("key"));
    }

    @Test
    public void getAttribute_WhenElementHasAttr_ReturnsValue() {
        Element element = new Element(tag, null, "value");
        assertEquals("value", element.attr("null"));
    }

    @Test
    public void hasAttr_WhenElementHasAttr_ReturnsTrue() {
        Element element = new Element(tag, "key", "value");
        assertTrue(element.hasAttr("key"));
    }

    @Test
    public void removeAttr_WhenElementHasAttr_RemovesAttr() {
        Element element = new Element(tag, "key", "value");
        element.removeAttr("key");
        assertFalse(element.hasAttr("key"));
    }

    // Text related tests

    @Test
    public void createElementWithText_ReturnsElementWithCorrectText() {
        Element element = new Element(tag, null, "text");
        assertEquals("text", element.text());
    }

    @Test
    public void text_WhenElementHasText_ReturnsValue() {
        Element element = new Element(tag, null, "text");
        assertEquals("text", element.text());
    }

    @Test
    public void hasText_WhenElementHasText_ReturnsTrue() {
        Element element = new Element(tag, null, "text");
        assertTrue(element.hasText());
    }

    @Test
    public void text_WhenElementDoesNotHaveText_ReturnsEmptyString() {
        Element element = new Element(tag, null, null);
        assertEquals("", element.text());
    }

    // HTML related tests

    @Test
    public void html_WhenElementHasHtml_ReturnsValue() {
        Element element = new Element(tag, "key", "value");
        assertEquals("<tag key=\"value\"></tag>", element.html().toString());
    }

    @Test
    public void clearAttributes_ClearsAllAttributes() {
        Element element = new Element(tag, "key1", "value1");
        element.clearAttributes();
        assertNull(element.attr("key1"));
    }
}
